#include "ui/MaterialPanel.hpp"
#include <imgui.h>
namespace scene_editor {void drawMaterialPanel(Scene& scene){ImGui::Begin("Material");if(auto* object=scene.find(scene.selectedId)){bool changed=false;changed|=ImGui::ColorEdit3("Base Color",&object->material.color.x);changed|=ImGui::ColorEdit3("Ambient",&object->material.ambient.x);changed|=ImGui::ColorEdit3("Diffuse",&object->material.diffuse.x);changed|=ImGui::ColorEdit3("Specular",&object->material.specular.x);changed|=ImGui::SliderFloat("Shininess",&object->material.shininess,1.0F,256.0F);static char path[512]{};static std::string selectedId;if(selectedId!=object->id){selectedId=object->id;snprintf(path,sizeof(path),"%s",object->material.texturePath.c_str());}if(ImGui::InputText("Texture path",path,sizeof(path))){object->material.texturePath=path;changed=true;}if(changed)object->materialOverride=true;}else ImGui::TextUnformatted("Select an object to edit its material.");ImGui::End();}}
